/* Glossary: powers the info buttons and the Words page. [emoji, term, plain meaning] */
const GLOSSARY = {
  rq: ["❓", "Research question", "The one clear question your study is trying to answer. Everything else in the study follows from it."],
  hypothesis: ["💡", "Hypothesis", "A clear guess you can check with data. For example: 'Plants with more light grow taller.'"],
  h0: ["🚫", "Null hypothesis (H0)", "The boring guess: 'nothing is going on, there is no difference.' You assume it is true until the data make it hard to believe."],
  h1: ["✅", "Alternative hypothesis (H1)", "The interesting guess: 'something is going on, there is a difference.' You only accept it if the data are very unlikely under H0."],
  aim: ["🎯", "Aim", "What the study sets out to understand. Studies that collect words and stories usually have an aim instead of a hypothesis to test."],
  pico: ["🧩", "Who, what, compared with, measured how", "Four building blocks of a question: the people you study, the thing that changes, what you compare it with, and what you measure. Researchers call this PICO."],
  population: ["🌍", "Population", "Everybody you want to learn about, such as all school children in India."],
  sample: ["🥄", "Sample", "The smaller group you actually study. Like tasting one spoonful to judge the whole pot of soup. It only works if the soup is well stirred."],
  random: ["🎲", "Random", "Decided by pure chance, like a coin flip or lucky draw. It stops anyone, including the researcher, from stacking the groups."],
  control: ["⚖️", "Control group", "The group that does not get the new thing. You need it to know what would have happened anyway."],
  placebo: ["🍬", "Placebo", "A dummy treatment, like a sugar pill, that looks the same as the real one, so people cannot tell which they got."],
  blind: ["🙈", "Blinding", "Hiding who is in which group, so that hopes and expectations cannot bend the results."],
  itt: ["📌", "Intention to treat", "Count everyone in the group they were first put in, even if they stopped or switched. It keeps the comparison fair."],
  power: ["🔦", "Power", "The chance your study will spot a real effect. Bigger studies are brighter torches."],
  pvalue: ["🎰", "P-value", "How surprising your result would be if nothing were really going on. A small P-value means 'this would be a rare fluke'. It is not the chance that your idea is right."],
  ci: ["↔️", "Confidence interval", "A range around your result that shows how unsure you are. Narrow range, more sure. Wide range, less sure."],
  moe: ["➕", "Margin of error", "How far a survey result might be from the truth just by the luck of who was picked. It does not cover badly worded questions or people who refused."],
  effect: ["📏", "Effect size", "How big the difference is. A result can be 'statistically significant' and still too small to matter."],
  multiple: ["🎯", "Multiple comparisons", "If you test lots of things, some will look exciting just by luck. The more shots you take, the more flukes you hit."],
  variable: ["🔤", "Variable", "Anything you measure that can differ between people or over time, like height, income or mood."],
  exposure: ["☀️", "Exposure", "The thing whose effect you are interested in, such as a treatment, habit, policy or pollutant."],
  outcome: ["🏁", "Outcome", "The result you measure at the end to see whether the exposure made a difference."],
  correlation: ["🔗", "Correlation", "Two things that tend to move together. It does not prove that one causes the other."],
  cause: ["⚡", "Causation", "One thing actually makes another happen more often. The hardest thing in research to prove."],
  confounder: ["🌦️", "Confounder", "A hidden third thing that affects both. Ice-cream sales and drownings both rise in summer: hot weather is the confounder."],
  reverse: ["🔃", "Reverse causation", "The arrow points the other way. Expensive shops do not make an area rich: they open where rich people already live."],
  bias: ["🧲", "Bias", "Anything that pulls your results away from the truth in one direction, such as only asking your friends."],
  selection: ["🚪", "Selection bias", "The people in your study, or in one of your groups, are different from the rest in a way that matters."],
  recall: ["🧠", "Recall bias", "People who got ill search their memories harder for causes than people who stayed well."],
  attrition: ["🚶", "Drop-out", "People leaving a study before it ends. If those who leave are different, the results tilt."],
  ascertain: ["🩻", "Ascertainment bias", "Some people are more likely to be checked, diagnosed or recorded than others, so they show up more in the data."],
  pubbias: ["🗄️", "Publication bias", "Exciting results get published. Dull ones stay in the drawer. Reading only journals gives too rosy a picture."],
  counterfactual: ["🪞", "Counterfactual", "What would have happened without the programme. You can never see it directly, so every design is a way of estimating it."],
  matching: ["👯", "Matching", "Pairing each person with a similar person in the other group, so the comparison is fairer."],
  parallel: ["🛤️", "Parallel trends", "The idea that two groups would have kept moving side by side if the new policy had not come."],
  carryover: ["💧", "Carry-over", "The first treatment is still working when the second one starts, which muddles the comparison."],
  interaction: ["🧪", "Interaction", "Two things together do more, or less, than you would expect from each alone."],
  cluster: ["🏘️", "Cluster", "A natural group such as a class or village. People inside one are more alike than strangers, so they count for less than fully separate people."],
  oddsratio: ["🎲", "Odds ratio", "A way of comparing how common something was in two groups. For rare events it is close to the relative risk."],
  relrisk: ["📣", "Relative risk", "How many times more likely something is in one group than another. '18% higher' sounds big but may be one extra case in a hundred."],
  bradford: ["🧾", "Bradford Hill checks", "Questions to ask before believing a link is a cause: Is the effect big? Did cause come first? Does more exposure mean more effect? Is there a sensible mechanism? Do other studies agree?"],
  rtm: ["↩️", "Regression to the mean", "Extreme results tend to be followed by more ordinary ones, with no cause needed. A terrible week is usually followed by a better one."],
  validity: ["🎯", "Validity", "Whether you are measuring the thing you mean to measure. A broken scale that always reads 2 kg too heavy is not valid."],
  reliability: ["🔁", "Reliability", "Whether you get the same answer when you measure again. A scale that gives a different weight each time is not reliable."],
  generalise: ["🌐", "Generalising", "Whether what you found in your study would also be true for other people, places or times."],
  replicate: ["👣", "Replication", "Someone else repeats the study and gets the same result. One study alone is rarely enough."],
  prereg: ["🔏", "Pre-registration", "Writing down your plan and locking it before you see the data, so you cannot change the rules after the game."],
  consent: ["✍️", "Informed consent", "People agree to take part after being told honestly what the study involves and that they can say no."],
  hawthorne: ["👀", "Being watched", "People often behave differently when they know someone is observing them."],
  framing: ["🖼️", "Framing", "The same fact can sound different depending on the words used. '90% survive' feels better than '10% die'."],
  anecdote: ["🗯️", "Anecdote", "A single story. It can raise a good question but cannot answer one."],
  ecofallacy: ["🗺️", "Ecological fallacy", "Assuming that what is true for a whole area is true for each person in it."],
  qualitative: ["🗣️", "Qualitative", "Research that collects words, pictures and meanings. Good for 'how' and 'why'."],
  quantitative: ["🔢", "Quantitative", "Research that collects numbers. Good for 'how many' and 'how much'."],
  coding: ["🏷️", "Coding", "Sticking short labels on pieces of text so you can gather similar ideas together later. Nothing to do with computer code."],
  theme: ["🧵", "Theme", "A bigger idea that ties many labels together, such as 'fear of losing income'."],
  saturation: ["🧽", "Saturation", "The point where new interviews stop telling you anything new. A sign you can stop collecting."],
  triangulation: ["📐", "Triangulation", "Checking a finding from several directions: different people, methods or sources. If they agree, trust grows."],
  reflexivity: ["🪞", "Reflexivity", "Thinking honestly about how you, the researcher, may be shaping what you see and hear."],
  bracketing: ["🧘", "Bracketing", "Deliberately setting your own beliefs to one side so you can hear someone else's experience clearly."],
  fieldnotes: ["📓", "Field notes", "The diary a researcher keeps of everything seen and heard while in the setting."],
  groupthink: ["🐑", "Group pressure", "People in a group going along with the loudest or most senior voice instead of saying what they think."],
  theory: ["🏗️", "Theory", "A well-organised explanation of why things happen, which can be tested or built on."],
  primary: ["📜", "Primary source", "First-hand evidence from the time, like a diary or original dataset, rather than someone's later summary."],
  participatory: ["🤲", "Participatory", "The people being studied help decide the questions, collect the evidence and use the results."],
  toc: ["🗺️", "Theory of change", "A step-by-step picture of how a project is supposed to lead to its results. Each arrow can be checked."],
  consensus: ["🤝", "Consensus", "Broad agreement in a group. Useful, but a group can agree and still be wrong."],
  necessary: ["🔑", "Necessary and sufficient", "Necessary: you cannot get the result without it. Sufficient: it is enough by itself to get the result."],
  peer: ["🧑‍⚖️", "Peer review", "Other experts check a study before it is published. Helpful, but not a guarantee."],
  protocol: ["📋", "Protocol", "The written plan for a study, fixed before it begins."],
  overfit: ["🧥", "Over-fitting", "A model that has memorised the old examples so closely, noise and all, that it does badly on new ones."],
  testset: ["🔒", "Test set", "Examples locked away and never used for training, so you can honestly check how good the model is."],
  baseline: ["📉", "Baseline", "A very simple guess to compare against. If your clever model cannot beat it, it has learned nothing."],
  trend: ["📈", "Trend", "The long-run direction of a number once you look past the short-term wiggles."],
  assumption: ["🧱", "Assumption", "Something you take as given so the calculation can go ahead. If it is wrong, so is the answer."],
  sensitivity: ["🎛️", "Sensitivity analysis", "Changing your assumptions one at a time to see whether the conclusion still holds."],
  sensitivity2: ["🎣", "Sensitivity (of a test)", "Out of everyone who really has the condition, the share the test catches."],
  specificity: ["🛡️", "Specificity", "Out of everyone who does not have the condition, the share the test correctly clears."],
  baserate: ["🪙", "Base rate", "How common something is to begin with. When a condition is rare, even a good test gives mostly false alarms."],
  f_time: ["⏳", "How long it takes", "A rough guide from first plan to result. Real projects vary a lot."],
  f_cost: ["💰", "How much it costs", "A rough guide to money and people needed compared with other methods."],
  f_data: ["🗃️", "Kind of data", "Numbers (counts and measurements), words (talk, text, observation notes), or both."],
  f_cause: ["⚡", "Can it show cause?", "Yes: built to show that one thing causes another. Partly: can get close if its assumptions hold. No: describes, explores or predicts, but cannot prove cause."],
  steps: ["👣", "How it works", "The method as a few simple steps, from left to right."],
  need: ["🎒", "What you need", "The things to have in place before you start. If one is missing, think about a different method."],
  how: ["🧮", "How you analyse it", "What you do with the data once you have it."],
  watch: ["⚠️", "Watch out", "The usual ways this method goes wrong. Good researchers say how they dealt with each."],
  example: ["🌟", "Example", "A study that used this method. 'Illustration' means it is made up to show the idea."],
  ppdac: ["🔄", "Problem, Plan, Data, Analysis, Conclusion", "Five steps every investigation goes through. A conclusion usually raises a new problem, so the cycle starts again."]
};
